# Fonts

`PublicSans-Variable.woff2`: Public Sans (variable, `wght` 100–900, all glyphs), SIL Open Font License 1.1 (`OFL.txt`).
Source: `google/fonts` `ofl/publicsans/PublicSans[wght].ttf` (sha256 `d75a7dc1…ca830a8`), converted with
`fonttools ttLib.woff2 compress`. Loaded by `next/font/local` in `src/app/layout.tsx`, so builds need no network.
import type { Metadata, Viewport } from "next";
import localFont from "next/font/local";
import { THEME_BOOT } from "@/lib/theme";
import "./globals.css";

// Public Sans from the repo (src/fonts): builds offline, no request to Google at build or run time.
const publicSans = localFont({
  src: "../fonts/PublicSans-Variable.woff2", weight: "100 900", style: "normal",
  variable: "--font-public-sans", display: "swap",
});

export const metadata: Metadata = { title: "Ocean Above", description: "Book flights in plain language" };
export const viewport: Viewport = {
  width: "device-width", initialScale: 1,
  themeColor: [{ media: "(prefers-color-scheme: light)", color: "#0e2f4a" }, { media: "(prefers-color-scheme: dark)", color: "#0a2236" }],
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={publicSans.variable} suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: THEME_BOOT }} />
      </head>
      <body>{children}</body>
    </html>
  );
}
@import "tailwindcss";

/* Direction A "Timetable" (docs/iterations/04-web/D1/design-proposal.md). Two themes: light (default) and dark.
   Theme = system unless <html data-theme="light|dark"> is set (components/theme-toggle.tsx). */
:root {
  --ground: #f3f5f7;      /* page */
  --surface: #ffffff;     /* cards, composer */
  --rail: #e9edf1;        /* conversation list, skeletons */
  --ink: #102030;         /* text, strong rules: 16.5:1 on surface */
  --ink-2: #4a5866;       /* secondary text: 7.3:1 on surface */
  --placeholder: #5e6b78; /* 5.5:1 */
  --hairline: #cbd3db;    /* 1px dividers (decorative) */
  --field: #8794a1;       /* input borders: 3.1:1 */
  --shell: #0e2f4a;       /* header band */
  --shell-ink: #ffffff;   /* 13.8:1 */
  --shell-ink-2: #b7c9d9; /* 8.1:1 */
  --accent: #0b5d8f;      /* primary action, focus, links, service line */
  --accent-hover: #094b74;
  --accent-ink: #ffffff;  /* text on accent: 7.1:1 */
  --accent-tint: #dde8f2; /* user message, selection: ink 13.3:1 */
  --ok: #1a6b34;    --ok-bg: #e6f4ea;     /* 5.8:1 */
  --warn: #7a4a00;  --warn-bg: #fff1d6;   /* 6.7:1 */
  --danger: #b42318; --danger-bg: #fdecea; /* 5.8:1 */
  --scrim: rgb(16 32 48 / 0.4);
  --overlay-shadow: 8px 0 24px rgb(16 32 48 / 0.18);
  color-scheme: light;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);
  --dur-1: 150ms; /* hover, colour */
  --dur-2: 200ms; /* enter, drawer */
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
  --ground: #0c1721;
  --surface: #15232f;
  --rail: #101d29;
  --ink: #e6edf3;         /* 13.5:1 on surface, 15.3:1 on ground */
  --ink-2: #a3b3c2;       /* 7.5:1 on surface, 8.0:1 on rail */
  --placeholder: #8a9bab; /* 5.6:1 */
  --hairline: #2a3b4a;
  --field: #5f7486;       /* 3.3:1 */
  --shell: #0a2236;
  --shell-ink: #ffffff;   /* 16.2:1 */
  --shell-ink-2: #9fb6ca; /* 7.7:1 */
  --accent: #4ba3db;      /* 5.8:1 on surface */
  --accent-hover: #6db6e6;
  --accent-ink: #06131d;  /* text on accent: 6.8:1 */
  --accent-tint: #1d3a52; /* ink on it 10.0:1 */
  --ok: #6fd08c;    --ok-bg: #12301e;     /* 7.6:1 */
  --warn: #f2b84b;  --warn-bg: #3a2a0a;   /* 7.7:1 */
  --danger: #ff8a7a; --danger-bg: #3d1714; /* 6.9:1 */
  --scrim: rgb(0 0 0 / 0.55);
  --overlay-shadow: 8px 0 24px rgb(0 0 0 / 0.5);
  color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --ground: #0c1721;
  --surface: #15232f;
  --rail: #101d29;
  --ink: #e6edf3;         /* 13.5:1 on surface, 15.3:1 on ground */
  --ink-2: #a3b3c2;       /* 7.5:1 on surface, 8.0:1 on rail */
  --placeholder: #8a9bab; /* 5.6:1 */
  --hairline: #2a3b4a;
  --field: #5f7486;       /* 3.3:1 */
  --shell: #0a2236;
  --shell-ink: #ffffff;   /* 16.2:1 */
  --shell-ink-2: #9fb6ca; /* 7.7:1 */
  --accent: #4ba3db;      /* 5.8:1 on surface */
  --accent-hover: #6db6e6;
  --accent-ink: #06131d;  /* text on accent: 6.8:1 */
  --accent-tint: #1d3a52; /* ink on it 10.0:1 */
  --ok: #6fd08c;    --ok-bg: #12301e;     /* 7.6:1 */
  --warn: #f2b84b;  --warn-bg: #3a2a0a;   /* 7.7:1 */
  --danger: #ff8a7a; --danger-bg: #3d1714; /* 6.9:1 */
  --scrim: rgb(0 0 0 / 0.55);
  --overlay-shadow: 8px 0 24px rgb(0 0 0 / 0.5);
  color-scheme: dark;
}

@theme inline {
  --font-sans: var(--font-public-sans), ui-sans-serif, system-ui, sans-serif;
  --color-background: var(--ground);
  --color-ground: var(--ground);
  --color-foreground: var(--ink);
  --color-ink: var(--ink);
  --color-muted: var(--ink-2);
  --color-ink-2: var(--ink-2);
  --color-border: var(--hairline);
  --color-hairline: var(--hairline);
  --color-field: var(--field);
  --color-card: var(--surface);
  --color-surface: var(--surface);
  --color-rail: var(--rail);
  --color-shell: var(--shell);
  --color-shell-ink: var(--shell-ink);
  --color-shell-ink-2: var(--shell-ink-2);
  --color-primary: var(--accent);
  --color-primary-fg: var(--accent-ink);
  --color-accent-ink: var(--accent-ink);
  --color-placeholder: var(--placeholder);
  --color-scrim: var(--scrim);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-tint: var(--accent-tint);
  --color-ok: var(--ok);
  --color-ok-bg: var(--ok-bg);
  --color-warn: var(--warn);
  --color-warn-bg: var(--warn-bg);
  --color-danger: var(--danger);
  --color-danger-bg: var(--danger-bg);
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --text-xs: 0.75rem;   --text-xs--line-height: 1rem;
  --text-sm: 0.875rem;  --text-sm--line-height: 1.25rem;
  --text-base: 1rem;    --text-base--line-height: 1.5rem;
  --text-lg: 1.125rem;  --text-lg--line-height: 1.5rem;
  --text-xl: 1.375rem;  --text-xl--line-height: 1.75rem;
  --text-2xl: 1.75rem;  --text-2xl--line-height: 2.25rem;
}

html, body { height: 100%; }
body {
  background: var(--ground);
  color: var(--ink);
  font-family: var(--font-sans);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
::selection { background: var(--accent-tint); color: var(--ink); }
input, textarea { caret-color: var(--accent); }
input::placeholder { color: var(--placeholder); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
* { scrollbar-color: var(--hairline) transparent; scrollbar-width: thin; }

/* Every figure is tabular so columns of km and $ line up. */
.figures { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1; }

@keyframes enter { from { opacity: 0; transform: translateY(4px); } }
.enter { animation: enter var(--dur-2) var(--ease-out) both; }
@keyframes drawer { from { transform: translateX(-16px); opacity: 0.6; } }
.drawer { animation: drawer var(--dur-2) var(--ease-out) both; }
@keyframes pulse-dot { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }
.typing span { animation: pulse-dot 1.2s var(--ease-out) infinite; }
.typing span:nth-child(2) { animation-delay: 0.2s; }
.typing span:nth-child(3) { animation-delay: 0.4s; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 0ms !important; }
}

/* Focus on the navy band: white ring (accent would be too dark there). */
[data-shell] :focus-visible { outline-color: var(--shell-ink); }
p { text-wrap: pretty; }
h1, h2 { text-wrap: balance; }
"use client";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useState, type ReactNode } from "react";
import { api, ApiError } from "@/lib/api";
import type { Me } from "@/lib/types";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { AccountIcon, CloseIcon, SignOutIcon } from "@/components/icons";
import { ThemeToggle } from "@/components/theme-toggle";

const NAV = [
  { href: "/chat", label: "Chat" },
  { href: "/tickets", label: "My tickets" },
  { href: "/history", label: "History" },
];

const PROVIDER: Record<Me["auth_provider"], string> = { google: "Google account", invite: "Invite code", dev: "Local account" };

/** "3 of 50 messages today" — both numbers straight from /api/me (no formatting or arithmetic here). */
export function usageText(u: Me["usage"]) {
  return `${u.messages_today} of ${u.daily_limit} messages today`;
}

/** Account panel content (desktop dropdown and phone menu). */
export function AccountPanel({ user, onSignOut }: { user: Me; onSignOut: () => void }) {
  return (
    <>
      <div className="px-1 pb-2">
        <p className="truncate font-semibold" data-testid="account-name">{user.display_name}</p>
        <p className="truncate text-sm text-ink-2">{user.email ?? PROVIDER[user.auth_provider]}</p>
        <p className="mt-2 text-sm text-ink-2" data-testid="usage">{usageText(user.usage)}</p>
      </div>
      <div className="sm:hidden">
        <div className="my-2 border-t border-hairline" />
        <p className="px-1 pb-1 text-xs font-semibold uppercase tracking-[0.06em] text-ink-2">Theme</p>
        <ThemeToggle />
      </div>
      <div className="my-2 border-t border-hairline" />
      <Button variant="ghost" className="w-full justify-start px-2" onClick={onSignOut}><SignOutIcon />Sign out</Button>
      <div className="mt-1 flex gap-1 border-t border-hairline pt-1 text-xs text-ink-2">
        <Link href="/privacy" className="inline-flex min-h-11 items-center px-1 hover:text-ink hover:underline">Privacy</Link>
        <Link href="/terms" className="inline-flex min-h-11 items-center px-1 hover:text-ink hover:underline">Terms</Link>
      </div>
    </>
  );
}

export type ShellApi = { user: Me; refreshUser: () => void };

/** Authenticated page frame: header + nav; redirects to /login on 401. */
export function Shell({ children, headerLeft }: { children: (s: ShellApi) => ReactNode; headerLeft?: ReactNode }) {
  const [user, setUser] = useState<Me | null>(null);
  const router = useRouter();
  const path = usePathname();
  const [menu, setMenu] = useState(false);
  useEffect(() => {
    if (!menu) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setMenu(false); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [menu]);
  async function signOut() { await api.logout().catch(() => {}); router.replace("/login"); }

  const refreshUser = useCallback(() => {
    api.me().then(setUser).catch((e) => {
      if (e instanceof ApiError && e.status === 401) router.replace("/login");
    });
  }, [router]);
  useEffect(() => { refreshUser(); }, [refreshUser]);

  if (!user) return <div className="p-6 text-ink-2" role="status">Loading…</div>;
  return (
    <div className="flex h-dvh flex-col">
      <header data-shell className="relative flex h-14 shrink-0 items-stretch gap-1 bg-shell px-2 text-shell-ink sm:gap-4 sm:px-4">
        {headerLeft}
        <span className="hidden items-center text-base font-bold tracking-[-0.01em] sm:inline-flex">Ocean Above</span>
        <nav className="flex flex-1 items-stretch" aria-label="Main">
          {NAV.map((n) => {
            const on = path.startsWith(n.href);
            return (
              <Link key={n.href} href={n.href} aria-current={on ? "page" : undefined}
                className={cn("inline-flex min-h-11 items-center border-b-[3px] px-3 pt-[3px] text-sm font-medium transition-colors duration-150",
                  on ? "border-white text-shell-ink" : "border-transparent text-shell-ink-2 hover:text-shell-ink")}>
                {n.label}
              </Link>
            );
          })}
        </nav>
        <ThemeToggle tone="shell" className="hidden self-center sm:inline-flex" />
        <Button variant="ghost" className="max-w-56 self-center px-3 text-shell-ink-2 hover:bg-white/10 hover:text-shell-ink"
          aria-label={`Account: ${user.display_name}`} aria-expanded={menu} aria-controls="shell-menu" onClick={() => setMenu((m) => !m)}>
          {menu ? <CloseIcon className="sm:hidden" /> : <AccountIcon className="sm:hidden" />}
          <AccountIcon className="hidden sm:block" />
          <span className="hidden truncate sm:inline">{user.display_name}</span>
        </Button>
        {menu && (
          <>
            <div className="fixed inset-0 z-30" onClick={() => setMenu(false)} aria-hidden />
            <div id="shell-menu" className="enter fixed top-14 right-2 z-40 w-64 rounded-lg border border-hairline bg-surface p-3 text-ink shadow-[0_8px_24px_rgb(0_0_0/0.18)] sm:right-4">
              <AccountPanel user={user} onSignOut={signOut} />
            </div>
          </>
        )}
      </header>
      <main className="min-h-0 flex-1">{children({ user, refreshUser })}</main>
    </div>
  );
}
"use client";
import type { Message } from "@/lib/types";
import type { Draft } from "@/lib/chat";
import { Markdown } from "@/components/markdown";
import { CardView } from "@/components/cards";
import { cn } from "@/lib/utils";

function Bubble({ m, streaming, readOnly, onBooked, onAsk }: { m: Pick<Message, "role" | "text" | "cards">; streaming?: boolean; readOnly?: boolean; onBooked?: () => void; onAsk?: (t: string) => void }) {
  const user = m.role === "user";
  return (
    <div className={cn("flex flex-col gap-2", user ? "items-end" : "items-start")}>
      {m.text && (
        <div className={cn("max-w-[85%] text-[0.9375rem] leading-6", user ? "rounded-xl rounded-br-sm bg-accent-tint px-4 py-2" : m.role === "system" ? "rounded-md bg-rail px-3 py-1.5 text-sm text-ink-2" : "max-w-[42rem] px-1")}>
          {user ? <p className="whitespace-pre-wrap break-words">{m.text}</p> : <Markdown text={m.text} streaming={streaming} />}
        </div>
      )}
      {m.cards.map((c, i) => <CardView key={i} card={c} streaming={streaming} readOnly={readOnly} onBooked={onBooked} onAsk={onAsk} />)}
    </div>
  );
}

export function MessageList({ messages, draft, readOnly, onBooked, onAsk }: { messages: Message[]; draft?: Draft | null; readOnly?: boolean; onBooked?: () => void; onAsk?: (t: string) => void }) {
  return (
    <div className="mx-auto max-w-3xl space-y-5" data-testid="messages">
      {messages.map((m) => <Bubble key={m.id} m={m} readOnly={readOnly} onBooked={onBooked} onAsk={onAsk} />)}
      {draft && (
        <>
          <Bubble m={{ role: "assistant", text: draft.text, cards: draft.cards }} streaming readOnly={readOnly} />
          {draft.status && !draft.text && <p className="flex items-center gap-2 px-1 text-sm text-ink-2" role="status"><span className="typing inline-flex gap-1" aria-hidden><span className="size-1.5 rounded-full bg-ink-2" /><span className="size-1.5 rounded-full bg-ink-2" /><span className="size-1.5 rounded-full bg-ink-2" /></span>{draft.status}</p>}
          {draft.error && <p className="text-sm text-danger" role="alert">{draft.error}</p>}
        </>
      )}
    </div>
  );
}
"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { api, ApiError } from "@/lib/api";
import { applyEvent, type ChatState } from "@/lib/chat";
import type { ConversationSummary } from "@/lib/types";
import { Shell } from "@/components/shell";
import { MessageList } from "@/components/message-list";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { EmptyState, ErrorState, LoadingState } from "@/components/states";
import { cn } from "@/lib/utils";
import { LimitNotice, type Limited } from "@/components/limit-notice";
import { CloseIcon, MenuIcon, PlusIcon, SendIcon } from "@/components/icons";

const EXAMPLES = ["I want to fly from Guangzhou to Lima", "Can I fly from Abu Dhabi?", "Which tickets do I have?"];

function ConversationList({ items, loading, activeId, onSelect, onNew }: { items: ConversationSummary[]; loading: boolean; activeId: string | null; onSelect: (id: string) => void; onNew: () => void }) {
  return (
    <div className="flex h-full flex-col gap-3 p-3">
      <Button variant="outline" className="justify-start" onClick={onNew}><PlusIcon size={18} />New chat</Button>
      <h2 className="px-3 pt-1 text-xs font-semibold uppercase tracking-[0.06em] text-ink-2">Conversations</h2>
      <ul className="-mt-1 min-h-0 flex-1 space-y-0.5 overflow-y-auto" aria-label="Conversations">
        {loading && <li className="px-3 py-2 text-sm text-ink-2" role="status">Loading conversations…</li>}
        {!loading && items.length === 0 && <li className="px-3 py-2 text-sm text-ink-2">No conversations yet.</li>}
        {items.map((c) => (
          <li key={c.id}>
            <button onClick={() => onSelect(c.id)}
              aria-current={c.id === activeId ? "true" : undefined}
              className={cn("block min-h-11 w-full rounded-md px-3 py-2 text-left text-sm transition-colors duration-150 hover:bg-ink/5", c.id === activeId && "bg-surface shadow-[inset_0_0_0_1px_var(--hairline)]")}>
              <span className="block truncate font-semibold">{c.title || "New chat"}</span>
              <span className="block truncate text-xs text-ink-2">{c.preview}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function Chat({ onUsage }: { onUsage?: () => void }) {
  const [list, setList] = useState<ConversationSummary[]>([]);
  const [listState, setListState] = useState<"loading" | "ready" | "error">("loading");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [state, setState] = useState<ChatState>({ messages: [], draft: null });
  const [loadingConv, setLoadingConv] = useState(false);
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);
  const [drawer, setDrawer] = useState(false);
  const drawerOpener = useRef<HTMLButtonElement>(null);
  const drawerClose = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!drawer) return;
    drawerClose.current?.focus();
    const opener = drawerOpener.current;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setDrawer(false); };
    window.addEventListener("keydown", onKey);
    return () => { window.removeEventListener("keydown", onKey); opener?.focus(); };
  }, [drawer]);
  const [error, setError] = useState<string | null>(null);
  const [limited, setLimited] = useState<Limited | null>(null);
  const [retry, setRetry] = useState<(() => void) | null>(null);
  const bottom = useRef<HTMLDivElement>(null);
  const streaming = state.draft !== null || sending;

  const load = useCallback(async (id: string) => {
    const c = await api.conversation(id);
    setState({ messages: c.messages, draft: null });
  }, []);

  const refreshList = useCallback(async () => { setList(await api.conversations()); }, []);

  const init = useCallback(async () => {
    setListState("loading"); setError(null); setRetry(null);
    try {
      const items = await api.conversations();
      setList(items); setListState("ready");
      if (items[0]) {
        setActiveId(items[0].id); setLoadingConv(true);
        try { await load(items[0].id); } finally { setLoadingConv(false); }
      }
    } catch (e) {
      setListState("error");
      setError(e instanceof Error ? e.message : "Could not load your conversations");
      setRetry(() => init);
    }
  }, [load]);

  useEffect(() => { init(); }, [init]);

  useEffect(() => { bottom.current?.scrollIntoView?.({ block: "end" }); }, [state]);

  async function select(id: string) {
    setDrawer(false); setActiveId(id); setError(null); setRetry(null); setLoadingConv(true);
    try { await load(id); } catch (e) {
      setState({ messages: [], draft: null });
      setError(e instanceof Error ? e.message : "Could not load this conversation");
      setRetry(() => () => select(id));
    } finally { setLoadingConv(false); }
  }
  async function newChat() {
    try {
      const c = await api.createConversation();
      setList((l) => [c, ...l]); setActiveId(c.id); setState({ messages: [], draft: null }); setDrawer(false); setError(null); setRetry(null);
    } catch (e) { setError(e instanceof Error ? e.message : "Could not start a new chat"); setRetry(() => newChat); }
  }

  /** Send a message. `fromInput`: the text came from the input box (cleared once the server stores it). */
  async function submit(t: string, fromInput = false) {
    t = t.trim();
    if (!t || streaming) return;
    setError(null); setRetry(null); setLimited(null); setSending(true);
    let id = activeId;
    let stored = false;          // user_message seen: the server kept the text
    let busy = false;            // conversation_busy: nothing stored, keep the input
    let limit: Limited | null = null; // 429 rate_limited: nothing stored, keep the input
    let streamError: string | null = null;
    let lost = false;
    try {
      if (!id) { const c = await api.createConversation(); id = c.id; setActiveId(id); }
      let s = state;
      await api.sendMessage(id, t, (ev) => {
        if (ev.event === "error" && ev.data.code === "conversation_busy" && !stored) { busy = true; return; }
        if (ev.event === "user_message") { stored = true; if (fromInput) setText((p) => (p.trim() === t ? "" : p)); }
        if (ev.event === "error") streamError = ev.data.message;
        s = applyEvent(s, ev); setState(s);
      });
    } catch (err) {
      if (err instanceof ApiError) {
        if (err.code === "conversation_busy") busy = true;
        else if (err.status === 429) limit = { scope: err.scope ?? null, message: err.message };
        else streamError = err.message;
      } else lost = true; // network drop
    }
    setSending(false);
    if (limit) {
      setState((s) => ({ ...s, draft: null }));
      setLimited(limit);
      onUsage?.();
      return; // nothing stored: no reload, input untouched
    }
    if (busy) {
      setState((s) => ({ ...s, draft: null }));
      setError("A reply is still being written. Your message is kept — try again in a moment.");
      return; // nothing stored: no reload, input untouched
    }
    // Stream over (done, error or disconnect): the server state wins.
    let reloaded = true;
    if (id) await load(id).catch(() => { reloaded = false; setState((s) => ({ ...s, draft: null })); });
    if (lost) {
      setError(reloaded ? "Connection lost. Showing the saved conversation." : "Connection lost and the conversation could not be reloaded.");
      if (!reloaded && id) { const cid = id; setRetry(() => () => select(cid)); }
    } else if (streamError) setError(streamError);
    refreshList().catch(() => {});
    onUsage?.();
  }

  function send(e: React.FormEvent) { e.preventDefault(); void submit(text, true); }

  return (
    <div className="relative flex h-full">
      <aside className="hidden w-72 shrink-0 border-r border-hairline bg-rail md:block">
        <ConversationList items={list} loading={listState === "loading"} activeId={activeId} onSelect={select} onNew={newChat} />
      </aside>
      {drawer && (
        <div className="fixed inset-0 z-20 md:hidden" role="dialog" aria-modal="true" aria-label="Conversations">
          <div className="absolute inset-0 bg-scrim" onClick={() => setDrawer(false)} />
          <div className="drawer absolute inset-y-0 left-0 flex w-80 max-w-[85vw] flex-col bg-rail shadow-[var(--overlay-shadow)]">
            <div className="flex justify-end px-1 pt-1"><Button ref={drawerClose} variant="ghost" aria-label="Close conversations" onClick={() => setDrawer(false)}><CloseIcon /></Button></div>
            <div className="min-h-0 flex-1"><ConversationList items={list} loading={listState === "loading"} activeId={activeId} onSelect={select} onNew={newChat} /></div>
          </div>
        </div>
      )}
      <section className="flex min-w-0 flex-1 flex-col" aria-labelledby="chat-title">
        <h1 id="chat-title" className="sr-only">Chat with Ocean Above</h1>
        <div className="flex items-center border-b border-hairline bg-surface px-1 md:hidden">
          <Button ref={drawerOpener} variant="ghost" className="gap-2 px-3" onClick={() => setDrawer(true)} aria-label="Open conversations" aria-expanded={drawer}><MenuIcon />Conversations</Button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-3 py-4 sm:px-6 sm:py-6">
          {loadingConv && <LoadingState label="Loading conversation…" />}
          {!loadingConv && listState !== "error" && state.messages.length === 0 && !state.draft && !error && (
            <EmptyState>
              <p className="text-lg font-semibold text-ink">Where would you like to fly?</p>
              <p className="mt-1">Describe your trip in your own words. You’ll see every leg, the distance and the price before anything is booked.</p>
              <div className="mt-4 flex flex-col items-stretch gap-2">
                {EXAMPLES.map((ex) => (
                  <Button key={ex} variant="outline" className="justify-start font-normal" onClick={() => setText(ex)}>{ex}</Button>
                ))}
              </div>
            </EmptyState>
          )}
          <MessageList messages={state.messages} draft={state.draft} onBooked={() => activeId && load(activeId).catch(() => {})} onAsk={(t) => void submit(t)} />
          {error && <div className="mt-3"><ErrorState message={error} onRetry={retry ?? undefined} /></div>}
          <div ref={bottom} />
        </div>
        <form onSubmit={send} className="border-t border-hairline bg-surface px-3 py-2 sm:px-6 sm:py-3">
          {limited && <LimitNotice limited={limited} />}
          <div className="mx-auto flex max-w-3xl gap-2">
            <Input value={text} onChange={(e) => setText(e.target.value)} placeholder="Where do you want to go?" aria-label="Message" className="flex-1" />
            <Button type="submit" aria-label="Send" disabled={streaming || !text.trim()}><SendIcon /><span className="hidden sm:inline">Send</span></Button>
          </div>
        </form>
      </section>
    </div>
  );
}

export default function ChatPage() {
  return <Shell>{({ refreshUser }) => <Chat onUsage={refreshUser} />}</Shell>;
}

