import { afterEach, describe, expect, it, vi } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { fixtureJson } from "./fixtures";

const router = { replace: vi.fn() }; // stable, like Next's router
vi.mock("next/navigation", () => ({ useRouter: () => router, usePathname: () => "/chat" }));
import { Shell, usageText } from "@/components/shell";

afterEach(() => { vi.restoreAllMocks(); vi.unstubAllGlobals(); });

describe("account and usage in the header", () => {
  it("usage text uses the two numbers from /api/me verbatim", () => {
    const me = fixtureJson("me");
    expect(usageText(me.usage)).toBe(`${me.usage.messages_today} of ${me.usage.daily_limit} messages today`);
  });

  it("header shows the name; the account menu shows email/provider, usage and legal links", async () => {
    const me = { ...fixtureJson("me"), display_name: "Ada", auth_provider: "google", email: "ada@example.com" };
    vi.stubGlobal("fetch", vi.fn(async () => new Response(JSON.stringify(me))));
    render(<Shell>{() => <p>child</p>}</Shell>);
    const btn = await screen.findByRole("button", { name: "Account: Ada" });
    await userEvent.click(btn);
    expect(screen.getByText("ada@example.com")).toBeInTheDocument();
    expect(screen.getByTestId("usage")).toHaveTextContent("3 of 50 messages today");
    expect(screen.getByRole("link", { name: "Privacy" })).toHaveAttribute("href", "/privacy");
    expect(screen.getByRole("link", { name: "Terms" })).toHaveAttribute("href", "/terms");
  });

  it("invite users (no email) see the sign-in method instead", async () => {
    const me = { ...fixtureJson("me"), auth_provider: "invite", email: null };
    vi.stubGlobal("fetch", vi.fn(async () => new Response(JSON.stringify(me))));
    render(<Shell>{() => null}</Shell>);
    await userEvent.click(await screen.findByRole("button", { name: /^Account:/ }));
    expect(screen.getByText("Invite code")).toBeInTheDocument();
  });

  it("refreshUser re-reads /api/me (usage after a send)", async () => {
    let n = 0;
    vi.stubGlobal("fetch", vi.fn(async () => new Response(JSON.stringify({ ...fixtureJson("me"), usage: { ...fixtureJson("me").usage, messages_today: n++ === 0 ? 3 : 4 } }))));
    let refresh: () => void = () => {};
    render(<Shell>{({ refreshUser }) => { refresh = refreshUser; return null; }}</Shell>);
    await userEvent.click(await screen.findByRole("button", { name: /^Account:/ }));
    expect(screen.getByTestId("usage")).toHaveTextContent("3 of 50");
    refresh();
    await waitFor(() => expect(screen.getByTestId("usage")).toHaveTextContent("4 of 50"));
  });
});
import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import { afterEach } from "vitest";
afterEach(() => cleanup());
export type Limited = { scope: "user" | "site" | null; message: string };

/** 429 rate_limited on send: which limit, the server's message (it states the reset time); nothing was stored. */
export function LimitNotice({ limited }: { limited: Limited }) {
  const title = limited.scope === "site" ? "The demo’s daily budget is used up" : "You’ve reached today’s message limit";
  return (
    <div role="alert" data-testid="rate-limited" className="mx-auto mb-2 max-w-3xl rounded-md border border-hairline bg-rail px-3 py-2 text-sm">
      <p className="font-semibold text-ink">{title}</p>
      <p className="text-ink-2">{limited.message} Your message is kept.</p>
    </div>
  );
}
"use client";
import { Fragment, memo, type ReactNode } from "react";
import { parseBlocks, parseInline, type Block, type Inline } from "@/lib/markdown";

function renderInline(nodes: Inline[]): ReactNode {
  return nodes.map((n, i) => {
    switch (n.t) {
      case "text": return <Fragment key={i}>{n.v}</Fragment>;
      case "br": return <br key={i} />;
      case "b": return <strong key={i}>{renderInline(n.c)}</strong>;
      case "i": return <em key={i}>{renderInline(n.c)}</em>;
      case "code": return <code key={i} className="rounded-sm bg-rail px-1 text-[0.9em]">{n.v}</code>;
      case "a": return <a key={i} href={n.href} target="_blank" rel="noopener noreferrer" className="text-primary underline">{renderInline(n.c)}</a>;
    }
  });
}

/** One block; memoised on its source so a streaming delta only re-renders the last block. */
const BlockView = memo(function BlockView({ src }: { src: string }) {
  const b = parseBlocks(src)[0] as Block | undefined;
  if (!b) return null;
  if (b.t === "p") {
    return <p>{b.lines.map((l, i) => <Fragment key={i}>{i > 0 && <br />}{renderInline(parseInline(l))}</Fragment>)}</p>;
  }
  const List = b.t === "ul" ? "ul" : "ol";
  return <List>{b.items.map((it, i) => <li key={i}>{renderInline(parseInline(it))}</li>)}</List>;
});

/** Split the source into block-sized chunks (same boundaries as parseBlocks). */
export function blockSources(text: string): string[] {
  const out: string[] = [];
  let cur: string[] = [], kind = "";
  const push = () => { if (cur.length) out.push(cur.join("\n")); cur = []; kind = ""; };
  for (const line of text.replace(/\r\n?/g, "\n").split("\n")) {
    if (!line.trim()) { push(); continue; }
    const k = /^\s{0,3}[-*+]\s+/.test(line) ? "ul" : /^\s{0,3}\d{1,9}[.)]\s+/.test(line) ? "ol" : "p";
    if (cur.length && (k === "p" ? kind !== "p" : kind !== k)) push();
    kind = k; cur.push(line);
  }
  push();
  return out;
}

export function Markdown({ text }: { text: string; streaming?: boolean }) {
  return (
    <div className="max-w-none break-words [&_p]:my-1 [&_ul]:my-1 [&_ol]:my-1 [&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_strong]:font-semibold">
      {blockSources(text).map((src, i) => <BlockView key={i} src={src} />)}
    </div>
  );
}

